CREATE TABLE customers (id UUID PRIMARY KEY, tenant_id UUID NOT NULL, name VARCHAR(150) NOT NULL, phone VARCHAR(40), email VARCHAR(254), address TEXT, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_customers_tenant_email UNIQUE (tenant_id,email), CONSTRAINT fk_customers_tenant FOREIGN KEY (tenant_id) REFERENCES tenants(id));
CREATE INDEX idx_customers_tenant_name ON customers (tenant_id,name);
CREATE TABLE suppliers (id UUID PRIMARY KEY, tenant_id UUID NOT NULL, business_name VARCHAR(150) NOT NULL, contact_person VARCHAR(150), phone VARCHAR(40), email VARCHAR(254), address TEXT, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_suppliers_tenant_email UNIQUE (tenant_id,email), CONSTRAINT fk_suppliers_tenant FOREIGN KEY (tenant_id) REFERENCES tenants(id));
CREATE INDEX idx_suppliers_tenant_name ON suppliers (tenant_id,business_name);
